set -eu; report_host=$(printf '%s\n' "$CLUSTER_HOSTS" | awk '$2=="node2" {print $1; exit}'); [ -n "$report_host" ]; umask 077; openssl rand -hex 24 > /root/branch_report.password; openssl rand -hex 24 > /root/branch_admin.password; report_pw=$(cat /root/branch_report.password); admin_pw=$(cat /root/branch_admin.password); mariadb <<SQL
CREATE USER IF NOT EXISTS 'branch_report'@'$report_host' IDENTIFIED BY [REDACTED]
ALTER USER 'branch_report'@'$report_host' IDENTIFIED BY [REDACTED]
GRANT SELECT ON branch_orders.customers TO 'branch_report'@'$report_host';
GRANT SELECT ON branch_orders.orders TO 'branch_report'@'$report_host';
CREATE USER IF NOT EXISTS 'branch_admin'@'localhost' IDENTIFIED BY [REDACTED]
ALTER USER 'branch_admin'@'localhost' IDENTIFIED BY [REDACTED]
GRANT ALL PRIVILEGES ON branch_orders.* TO 'branch_admin'@'localhost';
FLUSH PRIVILEGES;
SQL
